import itertools,pickle,time

def run(c):
 n=2*c
 full=(1<<n)-1
 masks=[sum(1<<i for i in s) for s in itertools.combinations(range(n),c)]
 # degree c on 2c vars; support bitset
 coord=[]
 for i in range(n):
  block=(1<<(1<<i))-1
  z=0
  for j in range(1<<i,1<<n,2<<i):z|=block<<j
  coord.append(z)
 words={}
 for mask in masks:
  v=(1<<(1<<n))-1
  for i in range(n):
   if mask>>i&1:v&=coord[i]
  words[mask]=v
 a=(1<<c)-1; A=words[a]
 result={0:(),2**c:(a,)}
 for bint in range(c+1):
  b=((1<<bint)-1)|(((1<<(c-bint))-1)<<c)
  B=words[b];result[(A^B).bit_count()]=(a,b)
  regions=[[i for i in range(n) if ((a>>i&1)+2*(b>>i&1))==j] for j in range(4)]
  for counts in itertools.product(*(range(len(reg)+1) for reg in regions)):
   if sum(counts)!=c:continue
   cc=sum(1<<i for reg,k in zip(regions,counts) for i in reg[:k])
   abc=A^B^words[cc]
   result[abc.bit_count()]=(a,b,cc)
   for dd,D in words.items():
    w=(abc^D).bit_count()
    if w not in result:result[w]=(a,b,cc,dd)
 print(c,sorted(w for w in result if w<5*2**(c-1)),flush=True)
 with open('mono%d.pkl'%c,'wb') as f:pickle.dump(result,f)
 return result
if __name__=='__main__':
 for c in range(3,8):
  t=time.time();run(c);print('secs',time.time()-t,flush=True)

